(function(){
'use strict';
const Engine=window.MiyarCompensation;if(!Engine)return;
const KEY='miyar-compensation-scenarios-v1';
const workspace=window.MiyarScenarioWorkspace.create({prefix:'cp',key:KEY,schema:'miyar-compensation-scenario/1.0',calculate:Engine.evaluate,values,fill,renderResult:result,bindResult:bind,resultAttribute:'result',fromInput:i=>({...i,targetCompaPercent:i.targetCompaPercent??100})});
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function ar(){return document.documentElement.lang!=='en';}function t(a,b){return ar()?a:b;}function money(v,c){if(v===null||v===undefined)return '—';return Number(v).toLocaleString(ar()?'ar-SA':'en-GB',{maximumFractionDigits:2})+' '+esc(c);}
function read(){return workspace.rows();}
function save(v){return workspace.save(v);}
function field(id,label,value='',attrs='',hint=''){return '<label class="cp-field">'+label+'<input id="cp-'+id+'" value="'+esc(value)+'" '+attrs+(hint?' aria-describedby="cp-'+id+'-hint"':'')+'>'+(hint?'<small id="cp-'+id+'-hint" class="cp-hint">'+hint+'</small>':'')+'</label>';}
function pct(v,d=1){if(v===null||!Number.isFinite(Number(v)))return '—';return Number(v).toLocaleString(ar()?'ar-SA':'en-GB',{maximumFractionDigits:d})+'%';}
function values(){return {payBasis:document.getElementById('cp-basis').value,role:document.getElementById('cp-role').value,grade:document.getElementById('cp-grade').value,headcount:document.getElementById('cp-headcount').value,currency:document.getElementById('cp-currency').value,period:document.getElementById('cp-period').value,bandSource:document.getElementById('cp-source').value,bandMin:document.getElementById('cp-min').value,bandMid:document.getElementById('cp-mid').value,bandMax:document.getElementById('cp-max').value,targetCompaPercent:document.getElementById('cp-target').value,...advancedValues(),currentSalary:document.getElementById('cp-current').value,oncostPercent:document.getElementById('cp-oncost').value,allowancesPercent:document.getElementById('cp-allowances')?.value??''};}
function fill(e){for(const [k,v] of Object.entries({role:e.role,grade:e.grade,headcount:e.headcount,currency:e.currency,source:e.bandSource,min:e.bandMin,mid:e.bandMid,max:e.bandMax,target:e.targetCompaPercent??100,current:e.currentSalary,oncost:e.oncostPercent,allowances:e.allowancesPercent})){const el=document.getElementById('cp-'+k);if(el)el.value=v??'';}document.getElementById('cp-period').value=e.period||'monthly';document.getElementById('cp-basis').value=e.payBasis||'basic';fillAdvanced(e);}
function gradeFromInstitution(role){const I=window.MiyarInstitutionProfile,p=I?.read?.();if(!I||!p||!String(role||'').trim())return'';const g=I.matchGrade(p,role);return g?g.id+' · '+(ar()?g.labelAr:g.labelEn):'';}
const zoneNames={'well-below':['أقل بكثير من المنتصف','Well below midpoint'],below:['دون المنتصف','Below midpoint'],at:['قريب من المنتصف — ليس تقييم أداء','Near midpoint — not a performance rating'],above:['فوق المنتصف','Above midpoint'],'well-above':['أعلى بكثير من المنتصف','Well above midpoint']};
const quartileNames={Q1:['الربع الأول من النطاق','First range quartile'],Q2:['الربع الثاني من النطاق','Second range quartile'],Q3:['الربع الثالث من النطاق','Third range quartile'],Q4:['الربع الرابع من النطاق','Fourth range quartile'],'below-minimum':['دون الحد الأدنى','Below minimum'],'above-maximum':['فوق الحد الأعلى','Above maximum']};
function guidance(v){const r=v.result,i=v.input,c=i.currency;
 if(r.payAction==='roster-review')return [t('مراجعة قائمة الشاغلين','Incumbent roster review'),t('حُسب كل شاغل براتبه الفعلي، ثم جُمعت الآثار. راجع الجدول الفردي قبل أي اعتماد.','Each incumbent uses their actual salary; impacts are summed. Review individual results before approval.')];
 if(r.payAction==='new-position')return [t('تقدير ميزانية لمنصب جديد','New-position budget estimate'),t('الهدف مشتق من المنتصف المعتمد. العرض الفعلي يتطلب سياسة التعيين وخبرة المرشح والاعتماد.','Target is derived from the approved midpoint. An actual offer requires hiring policy, candidate evidence and approval.')];
 if(r.payAction==='increase')return [t('اقتراح تعويض للمراجعة','Compensation proposal for review'),t('زيادة '+money(r.adjustmentPerFte,c)+' لكل FTE ('+pct(r.adjustmentPercent)+') للوصول إلى الهدف.','An increase of '+money(r.adjustmentPerFte,c)+' per FTE ('+pct(r.adjustmentPercent)+') reaches the target.')+(r.adjustmentPercent>15?t(' تعديل كبير: فكّر في جدولته على أكثر من دورة مراجعة.',' Large adjustment: consider phasing it across review cycles.'):'')];
 if(r.payAction==='hold')return [t('تثبيت الراتب داخل النطاق','Hold within-band salary'),t('الموضع داخل النطاق لا يبرر زيادة تلقائية. التقدم الاختياري يحتاج سياسة معتمدة ودليل أداء أو خبرة للفرد.','Range position alone does not justify an increase. Optional progression needs approved policy and individual performance or experience evidence.')];
 if(r.payAction==='below-band')return [t('تصحيح إلى الحد الأدنى لنطاق الجهة','Correction to organization band minimum'),t('أثر التصحيح السنوي: '+money(r.annualMinimumAdjustmentCost,c)+'. هذا تطبيق لسياسة نطاق الجهة للمراجعة، وليس تحديدًا لحد أدنى نظامي. التقدم الإضافي منفصل.','Annual correction cost: '+money(r.annualMinimumAdjustmentCost,c)+'. Organization band policy proposal for review, not a statutory minimum determination. Additional progression is separate.')];
 return [t('أعلى من النطاق — تثبيت للمراجعة','Above band — red-circle / hold for review'),t('لا تخفيض. أوقف زيادات الراتب الأساسي حتى يلحق النطاق، واستخدم مكافآت مقطوعة غير مضافة للأساس عند الأداء المتميز.','No reduction. Pause base increases until the band catches up and use non-consolidated lump sums for strong performance.')];}
function rangeBar(v){const i=v.input,r=v.result,pos=r.currentRangePenetrationPercent,clamp=n=>Math.max(0,Math.min(100,n));return '<div class="cp-range" dir="ltr"><div class="cp-line"><span style="left:0%"></span><span style="left:25%"></span><span style="left:50%"></span><span style="left:75%"></span><span style="left:100%"></span><i class="cp-target" style="left:'+i.targetPenetrationPercent+'%" title="'+t('الهدف','Target')+'"></i>'+(pos===null?'':'<i class="cp-current" style="left:'+clamp(pos)+'%" title="'+t('الراتب الحالي','Current salary')+'"></i>')+'</div><div class="cp-scale"><span>'+t('الحد الأدنى','Min')+'</span><span>'+t('الربع 1','Q1')+'</span><span>'+t('وسط النطاق','Range centre')+'</span><span>'+t('الربع 3','Q3')+'</span><span>'+t('الحد الأعلى','Max')+'</span></div><div class="cp-legend" dir="auto"><span><i class="cp-target"></i>'+t('الهدف','Target')+'</span>'+(pos===null?'':'<span><i class="cp-current"></i>'+t('الراتب الحالي','Current salary')+'</span>')+'</div></div>';}
function diagnosticsView(v){const d=v.bandDiagnostics,spread={undefined:['غير قابل للحساب عندما يكون الحد الأدنى صفرًا','Not computable when the minimum is zero'],narrow:['ضيق — مساحة تقدم محدودة داخل الدرجة','Narrow — limited progression room within the grade'],common:['ضمن حدود الفحص التوضيحية','Within illustrative review thresholds'],wide:['واسع — فكّر في مناطق داخل النطاق أو تقسيم الدرجة','Wide — consider zones within the band or splitting the grade']}[d.spreadAssessment];return '<div class="cp-diagnostics"><strong>'+t('فحص تصميم النطاق','Band design check')+'</strong><ul><li class="'+(d.spreadAssessment==='common'?'ok':'warn')+'">'+t('اتساع النطاق ','Range spread ')+pct(d.rangeSpreadPercent)+' · '+t(...spread)+'</li><li class="'+(d.midpointCentred?'ok':'warn')+'">'+(d.midpointCentred?t('المنتصف في وسط النطاق','Midpoint is centred in the band'):t('المنتصف منحرف '+pct(d.midpointOffsetPercent)+' عن الوسط — تحقق من البيانات','Midpoint is offset '+pct(d.midpointOffsetPercent)+' from the centre — check the data'))+'</li></ul><small>'+t('20–75% حدود تنبيه توضيحية وليست معيارًا سوقيًا. اختلاف المنتصف المعتمد عن وسط النطاق جائز ويحتاج فهم سياسة الجهة.','20–75% are illustrative review triggers, not a market standard. An approved midpoint may differ from the range centre; review the organization policy.')+'</small></div>';}
function costView(v){const r=v.result,i=v.input,c=i.currency;if(v.incumbents||i.employerCosts?.mode==='saudi'||!i.allowancesApplied)return '';return '<div class="cp-cost"><strong>'+t('تكلفة الحزمة السنوية','Annual package cost')+'</strong><dl><dt>'+t('الراتب الأساسي','Basic pay')+'</dt><dd>'+money(r.annualBasePayroll,c)+'</dd><dt>'+t('البدلات الثابتة','Fixed allowances')+' ('+pct(i.allowancesPercent)+')</dt><dd>'+money(r.annualGuaranteedCash-r.annualBasePayroll,c)+'</dd><dt>'+t('الأجر النقدي المضمون','Guaranteed cash')+'</dt><dd>'+money(r.annualGuaranteedCash,c)+'</dd><dt>'+t('تكلفة صاحب العمل الإضافية','Employer on-cost')+' ('+pct(i.oncostPercent)+')</dt><dd>'+money(r.annualEmployerCost-r.annualGuaranteedCash,c)+'</dd></dl></div>';}
function result(v){const r=v.result,i=v.input,c=i.currency,period=t(i.period==='monthly'?'شهري':'سنوي',i.period==='monthly'?'Monthly':'Annual'),g=guidance(v);return '<section class="cp-result"><div class="cp-result-head"><div><span>'+t('المرحلة 3 · نطاق الجهة','PHASE 3 · ORGANIZATION BAND')+'</span><h2>'+esc(i.role||t('سيناريو التعويض','Compensation scenario'))+'</h2><p>'+esc(i.grade||t('الدرجة غير محددة','Grade not specified'))+' · '+period+'</p></div><strong>'+money(r.payAction==='roster-review'?r.annualEmployerCost:r.recommendedSalary??r.targetSalary,c)+'</strong></div><div class="decision-summary"><strong>'+t('ماذا يعني هذا لقرارك؟','What this means for your decision')+'</strong><p>'+esc(g[0]+' — '+g[1]+' '+t('التكلفة السنوية على صاحب العمل: ','Annual employer cost: ')+Number(r.annualEmployerCost).toLocaleString(ar()?'ar-SA':'en-GB',{maximumFractionDigits:0})+' '+c+'.')+'</p></div><div class="cp-metrics"><div><span>'+t('الحد الأدنى','Minimum')+'</span><b>'+money(i.bandMin,c)+'</b></div><div><span>'+t('المنتصف','Midpoint')+'</span><b>'+money(i.bandMid,c)+'</b></div><div><span>'+t('الحد الأعلى','Maximum')+'</span><b>'+money(i.bandMax,c)+'</b></div><div><span>'+t('موضع الهدف داخل النطاق','Target range position')+'</span><b>'+pct(i.targetPenetrationPercent)+'</b></div><div><span>'+t('نسبة المقارنة بالمنتصف (Compa-ratio)','Compa-ratio')+'</span><b>'+(r.compaRatio===null?'—':Number(r.compaRatio).toLocaleString(ar()?'ar-SA':'en-GB',{maximumFractionDigits:3}))+'</b>'+(r.compaZone?'<small>'+t(...zoneNames[r.compaZone])+(r.currentQuartile?' · '+t(...quartileNames[r.currentQuartile]):'')+'</small>':'')+'</div><div><span>'+t('إجمالي تكلفة صاحب العمل سنويًا','Annual employer cost')+'</span><b>'+money(r.annualEmployerCost,c)+'</b></div></div>'+rangeBar(v)+(v.incumbents?'<div class="cp-adjust"><strong>'+t('إجمالي أثر التعديل السنوي للقائمة','Total annual roster adjustment')+': '+money(r.annualAdjustmentCost,c)+'</strong><span>'+t('نسبة المقارنة والفرق الفردي يُراجعان لكل شاغل؛ لا يمثل القائمة راتب واحد.','Review compa-ratio and individual changes per incumbent; one salary does not represent the roster.')+'</span></div>':r.adjustmentPerFte===null?'<p class="cp-note">'+t('لم يُدخل راتب حالي/مرجعي؛ لذلك تبقى نسبة Compa-ratio وتكلفة التعديل غير معروفتين بدل عرض صفر.','No current/reference salary was provided, so compa-ratio and adjustment cost remain unknown rather than displaying zero.')+'</p>':'<div class="cp-adjust"><strong>'+t('الفرق لكل FTE','Difference per FTE')+': '+money(r.adjustmentPerFte,c)+'</strong><span>'+t('الأثر السنوي شامل تكلفة صاحب العمل','Annual adjustment including employer on-cost')+': '+money(r.annualAdjustmentCost,c)+'</span></div>')+'<div class="cp-policy"><strong>'+g[0]+'</strong><p>'+esc(g[1])+'</p><p class="cp-basis">'+t('أساس الحساب: '+(i.payBasis==='total'?'الأجر الإجمالي':'الأجر الأساسي')+'. نسبة التكلفة بحسب النموذج المختار؛ عند اختيار التفصيل السعودي تُحسب البنود من سجل الاشتراك والتاريخ المدخلين.','Pay basis: '+(i.payBasis==='total'?'total cash pay':'basic salary')+'. Employer cost follows the selected model; Saudi breakdown uses the confirmed registration regime and selected date.')+(i.payBasis==='total'&&i.allowancesPercent?t(' البدلات مشمولة في الأجر الإجمالي ولم تُضف مرة أخرى.',' Allowances are already inside total cash pay and were not added again.'):'')+'</p></div>'+costView(v)+advancedResult(v)+diagnosticsView(v)+'<div class="cp-warning"><strong>'+t('ليس Benchmark سوقي','Not a market benchmark')+'</strong><p>'+esc(t('الحساب يستخدم فقط نطاق الراتب الذي أدخلته الجهة ومصدره. الربعان Q1 وQ3 مواضع داخل نطاق الجهة وليست مئينات سوقية. لا يستنتج عدالة الأجر ولا قيمة السوق ولا يصدر اعتماد تعويضات.','The calculation uses only the organization-provided salary band and source. Q1 and Q3 are positions inside the organization band, not market percentiles. It does not infer pay equity, market value or compensation approval.'))+'</p></div><div class="action-row"><button type="button" class="button button-primary" data-cp-save>'+t('حفظ السيناريو','Save scenario')+'</button><button type="button" class="button button-outline" data-cp-export>'+t('تصدير JSON','Export JSON')+'</button></div><p data-cp-status role="status"></p></section>';}
function bind(v){const root=document.querySelector('.cp-result');root.querySelector('[data-cp-save]').onclick=()=>{try{const r=save(v);root.querySelector('[data-cp-status]').textContent=t('حُفظ السيناريو: ','Scenario saved: ')+r.id;}catch(e){workspace.fail(e);}};root.querySelector('[data-cp-export]').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(v,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='miyar-compensation-scenario.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);};}
function render(){if(location.hash!=='#enterprise/compensation')return;const content=document.getElementById('ent-content');if(!content)return;document.getElementById('enterprise-heading').textContent=t('التعويضات','Compensation');const bc=document.getElementById('breadcrumb-title');if(bc)bc.textContent=t('التعويضات','Compensation');document.querySelectorAll('.nav-link').forEach(x=>x.classList.remove('active'));document.querySelector('[data-comp-nav]')?.classList.add('active');let pending=null;try{pending=JSON.parse(sessionStorage.getItem('miyar-compensation-handoff')||'null');}catch{}content.innerHTML='<section class="cp-page"><div class="cp-heading"><div><span>'+t('المرحلة 3 · التعويضات','PHASE 3 · COMPENSATION')+'</span><h2>'+t('اربط الدرجة بنطاق التعويض المعتمد لدى الجهة','Link the grade to the organization-approved compensation band')+'</h2><p>'+t('معيار لا يخترع رواتب سوقية. أدخل نطاق الجهة ومصدره، ثم احسب موضع الراتب والأثر على التكلفة بشكل قابل للمراجعة.','Miyar does not invent market salaries. Enter the organization band and its source, then calculate salary positioning and cost impact transparently.')+'</p></div><button type="button" class="button button-outline" data-cp-example>'+t('تحميل مثال توضيحي','Load illustrative example')+'</button></div><div class="cp-form">'+field('role',t('الدور / المنصب','Role / position'),pending?.role||'')+field('grade',t('الدرجة','Grade'),pending?.grade||gradeFromInstitution(pending?.role||''))+field('headcount',t('عدد أفراد متشابهين — تتجاوزه قائمة الشاغلين','Identical-pay cohort count — roster overrides'),pending?.headcount||1,'type="number" min="1" step="1"')+field('currency',t('العملة','Currency'),'SAR','maxlength="3"')+'<label class="cp-field">'+t('فترة النطاق','Band period')+'<select id="cp-period"><option value="monthly">'+t('شهري','Monthly')+'</option><option value="annual">'+t('سنوي','Annual')+'</option></select></label>'+'<label class="cp-field">'+t('أساس النطاق والراتب','Band and salary basis')+'<select id="cp-basis"><option value="basic">'+t('الراتب الأساسي','Basic salary')+'</option><option value="total">'+t('إجمالي الأجر النقدي','Total cash pay')+'</option></select></label>'+field('source',t('مصدر نطاق الراتب / مرجع الجهة','Salary-band source / organization reference'),'')+field('min',t('الحد الأدنى','Minimum'),'','type="number" min="0" step="any"')+field('mid',t('المنتصف','Midpoint'),'','type="number" min="0" step="any"')+field('max',t('الحد الأعلى','Maximum'),'','type="number" min="0" step="any"')+field('target',t('الهدف كنسبة من المنتصف المعتمد %','Target as % of approved midpoint'),'100','type="number" min="1" max="300" step="1"')+field('current',t('راتب حالي/مرجعي — اختياري','Current/reference salary — optional'),'','type="number" min="0" step="any"')+field('oncost',t('تكلفة صاحب العمل الإضافية %','Employer on-cost %'),'0','type="number" min="0" max="200" step="0.1"',t('حصة صاحب العمل في التأمينات، التأمين الطبي، مخصص نهاية الخدمة ومزايا أخرى — حسب سياسة الجهة.','Employer social-insurance share, medical insurance, end-of-service accrual and other benefits — per organization policy.'))+field('allowances',t('البدلات الثابتة % من الأساسي — اختياري','Fixed allowances % of basic — optional'),'','type="number" min="0" max="200" step="0.1"',t('مثل السكن والنقل حسب سياسة الجهة؛ تُتجاهل إذا كان النطاق على إجمالي الأجر.','For example housing and transport per organization policy; ignored when the band is on total cash pay.'))+'</div><div class="cp-run"><button type="button" class="button button-primary" data-cp-run>'+t('احسب موضع التعويض','Calculate compensation position')+'</button><span data-cp-message role="status">'+t('يجب أن يكون النطاق من مصدر داخلي معتمد أو مبرر موثق.','The band must come from an approved internal source or documented rationale.')+'</span></div><div data-cp-result></div></section>';content.querySelector('.cp-form').insertAdjacentHTML('beforeend',advancedFields());sessionStorage.removeItem('miyar-compensation-handoff');content.querySelector('[data-cp-example]').onclick=()=>workspace.example(Engine.example);content.querySelector('[data-cp-run]').onclick=()=>workspace.calculate();if(pending)workspace.example({...pending,period:'monthly',currency:'SAR',targetCompaPercent:100,oncostPercent:0});workspace.mount(content);bindAdvanced(content);}

function ensureNav(){const nav=document.querySelector('.sidebar nav.nav-list');if(!nav)return;let link=nav.querySelector('[data-comp-nav]');if(!link){link=document.createElement('a');link.href='#enterprise/compensation';link.className='nav-link';link.dataset.compNav='true';link.innerHTML='<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16v12H4zM7 4h10v3M8 12h8m-4-3v6"/></svg><span>'+t('التعويضات','Compensation')+'</span>';const mp=nav.querySelector('[data-manpower-nav]'),grade=nav.querySelector('[data-enterprise-open="grading"]');(mp||grade)?.after(link);}else link.querySelector('span').textContent=t('التعويضات','Compensation');}
// A language switch replaces the shell without a route or enterprise event.
new MutationObserver(ensureNav).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
function injectManpowerLink(){if(location.hash!=='#enterprise/manpower')return;const actions=document.querySelector('.mp-results .action-row'),plan=window.MiyarManpowerWorkbench?.getResult?.();if(!actions||actions.querySelector('[data-cp-from-mp]')||!plan||plan.scenarios.base.final.rawGapFte<=.5)return;const btn=document.createElement('button');btn.type='button';btn.className='button button-outline';btn.dataset.cpFromMp='true';btn.textContent=t('احسب أثر التعويض','Estimate compensation impact');actions.append(btn);btn.onclick=()=>{const current=window.MiyarManpowerWorkbench.getResult();if(!current||current.scenarios.base.final.rawGapFte<=.5)return;sessionStorage.setItem('miyar-compensation-handoff',JSON.stringify({role:current.input.role,grade:gradeFromInstitution(current.input.role),headcount:current.scenarios.base.final.gapHeadcount}));location.hash='#enterprise/compensation';};}
window.addEventListener('miyar:scenario-result',e=>{if(e.detail.prefix==='mp')injectManpowerLink();});
window.addEventListener('hashchange',()=>setTimeout(()=>{ensureNav();render();injectManpowerLink();},0));window.addEventListener('miyar:navigate',()=>setTimeout(()=>{ensureNav();render();injectManpowerLink();},0));document.addEventListener('click',e=>{const link=e.target.closest('[data-comp-nav]');if(link){e.preventDefault();location.hash='#enterprise/compensation';setTimeout(render,0);}if(e.target.closest('[data-mp-run]'))setTimeout(injectManpowerLink,0);});setTimeout(()=>{ensureNav();render();injectManpowerLink();},0);window.MiyarCompensationWorkbench={KEY,read,render};
function advancedFields(){const box=(id,label)=>'<label class="cp-check"><input type="checkbox" id="cp-'+id+'">'+label+'</label>';return '<section class="cp-advanced"><h3>'+t('قرار التعويض وأدلة المراجعة','Pay decision and review evidence')+'</h3><p>'+t('لا زيادة تلقائية داخل النطاق. تصحيح الحد الأدنى منفصل عن التقدم الاختياري.','No automatic within-band increases. Minimum correction is separate from optional progression.')+'</p>'+box('progression',t('تضمين تقدم اختياري وفق سياسة الجهة','Include optional progression under organization policy'))+box('approved',t('تحققت من اعتماد سياسة التقدم','I verified progression policy approval'))+field('policy',t('مرجع سياسة التقدم','Progression policy reference'))+field('evidence',t('دليل الأداء أو الخبرة للفرد','Individual performance or experience evidence'))+box('units',t('راجعت الفترة والعملة والوحدات وحجم القائمة','I reviewed period, currency, units and cohort scale'))+'<details><summary>'+t('قائمة الشاغلين — رواتب فعلية لكل فرد','Incumbent roster — actual individual salaries')+'</summary><p>'+t('استخدم رموزًا مستعارة فقط. الحساب محلي في المتصفح، والحفظ اختياري. جميع الصفوف تستخدم نطاق الجهة نفسه؛ حلّل الدرجات المختلفة في قوائم منفصلة.','Use pseudonymous IDs only. Calculation stays in this browser; saving is optional. All rows share this band; use separate lists for different grades.')+'</p><label class="cp-field">'+t('ملف CSV','CSV file')+'<input type="file" id="cp-roster-file" accept=".csv,text/csv"></label><label class="cp-field">'+t('محتوى CSV — راجعه قبل الحساب','CSV content — review before calculating')+'<textarea id="cp-roster" rows="5" dir="ltr" placeholder="id,currentSalary&#10;P001,25000&#10;P002,23000"></textarea></label><button type="button" class="button button-outline" data-cp-template>'+t('تنزيل قالب الشاغلين','Download roster template')+'</button></details><details><summary>'+t('تفصيل تكلفة صاحب العمل السعودي','Saudi employer-cost breakdown')+'</summary><p>'+t('اختر النظام من سجل المشترك؛ الجنسية وحدها لا تكفي. الحالات الخليجية والخاصة تحتاج حساب المختص. يتطلب أساسي SAR وتصفير نسب العبء والبدلات العامة لمنع الازدواج.','Select the regime from the registration record; nationality alone is insufficient. GCC and special cases need specialist calculation. Requires SAR basic pay and zero generic on-cost/allowance percentages to avoid double counting.')+'</p>'+box('saudi',t('استخدام التفصيل السعودي','Use Saudi breakdown'))+box('applicability',t('راجعت نظام الاشتراك ومكونات الأجر الخاضع للاشتراك','I verified registration regime and contributory wage components'))+'<label class="cp-field">'+t('نظام الاشتراك','Registration regime')+'<select id="cp-regime"><option value="">'+t('اختر من السجل','Choose from record')+'</option><option value="saudi-existing">'+t('سعودي — النظام القائم','Saudi — existing regime')+'</option><option value="saudi-new">'+t('سعودي — مشمول بالنظام الجديد','Saudi — new regime')+'</option><option value="non-saudi">'+t('غير سعودي — الأخطار المهنية فقط','Non-Saudi — occupational hazards only')+'</option></select></label>'+field('asof',t('تاريخ احتساب النسب','Rate calculation date'),'2026-10-05','type="date" min="2024-07-03" max="2028-12-31"')+box('saned',t('ساند منطبق وفق سجل المشترك','SANED applies per registration record'))+field('housing',t('بدل السكن النقدي شهريًا SAR','Monthly cash housing SAR'),'','type="number" min="0"')+field('othercash',t('البدلات النقدية الأخرى شهريًا SAR','Other monthly cash SAR'),'','type="number" min="0"')+field('contributory',t('مكونات إضافية خاضعة للتأمينات شهريًا SAR','Additional monthly GOSI contributory components SAR'),'','type="number" min="0"',t('مثل عمولات مستحقة أو قيمة سكن عيني مراجعة؛ تأكد أنها ضمن النقد أو المزايا المعتمدة.','For reviewed commissions or in-kind housing valuation; reconcile against cash and benefit records.'))+field('medical',t('التأمين الطبي السنوي للفرد SAR','Annual medical cost per person SAR'),'','type="number" min="0"')+field('service',t('سنوات الخدمة المكتملة','Completed years of service'),'','type="number" min="0" max="60" step="0.01"')+field('eos',t('أجر نهاية الخدمة الشهري — اختياري','EOS monthly wage — optional'),'','type="number" min="0.01"',t('الفارغ يستخدم الأساسي + السكن + البدلات النقدية المدخلة؛ تحقق من الأجر النظامي لدى المختص.','Blank uses basic + entered cash housing + other cash; have a specialist verify the applicable wage.'))+'</details></section>';}
function advancedValues(){const val=id=>document.getElementById('cp-'+id)?.value||'',checked=id=>document.getElementById('cp-'+id)?.checked===true;return {progressionEnabled:checked('progression'),progressionApproved:checked('approved'),progressionPolicy:val('policy'),progressionEvidence:val('evidence'),unitsConfirmed:checked('units'),rosterCsv:val('roster'),employerCosts:checked('saudi')?{mode:'saudi',applicabilityConfirmed:checked('applicability'),regime:val('regime'),asOf:val('asof'),sanedEligible:checked('saned'),housingMonthly:val('housing'),otherMonthly:val('othercash'),contributoryExtraMonthly:val('contributory'),medicalAnnual:val('medical'),serviceYears:val('service'),eosWageMonthly:val('eos')}:null};}
function rosterText(rows){const headers=Engine.rosterColumns;return headers.join(',')+'\n'+rows.map(r=>headers.map(h=>{const v=r[h]??r.employerCosts?.[h]??'';return '"'+String(v).replace(/"/g,'""')+'"';}).join(',')).join('\n');}
function fillAdvanced(e){const b=e.employerCosts||{},values={policy:e.progressionPolicy,evidence:e.progressionEvidence,roster:e.incumbents?rosterText(e.incumbents):e.rosterCsv,regime:b.regime,asof:b.asOf||'2026-10-05',housing:b.housingMonthly,othercash:b.otherMonthly,contributory:b.contributoryExtraMonthly,medical:b.medicalAnnual,service:b.serviceYears,eos:b.eosWageMonthly};for(const [k,v]of Object.entries(values)){const el=document.getElementById('cp-'+k);if(el)el.value=v??'';}for(const [k,v]of Object.entries({progression:e.progressionEnabled,approved:e.progressionApproved,units:e.unitsConfirmed,saudi:b.mode==='saudi',applicability:b.applicabilityConfirmed,saned:b.sanedEligible})){const el=document.getElementById('cp-'+k);if(el)el.checked=v===true;}}
function bindAdvanced(content){const f=content.querySelector('#cp-roster-file');if(!f)return;f.onchange=async()=>{try{const file=f.files[0];if(!file)return;if(file.size>250000)throw Error(t('الحد 250 كيلوبايت','Maximum 250 KB'));const text=await file.text();Engine.parseRoster(text);const target=content.querySelector('#cp-roster');target.value=text;target.dispatchEvent(new Event('input',{bubbles:true}));}catch(e){workspace.fail(e);}finally{f.value='';}};content.querySelector('[data-cp-template]').onclick=()=>{const data=rosterText([{id:'P001',currentSalary:25000,progressionEligible:false,employerCosts:{regime:'saudi-existing',housingMonthly:0,otherMonthly:0,contributoryExtraMonthly:0,medicalAnnual:4000,serviceYears:2,sanedEligible:true}}]);const url=URL.createObjectURL(new Blob(['\uFEFF'+data],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='miyar-incumbents-template.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);};}
function advancedResult(v){const c=v.input.currency,r=v.result,b=v.employerBreakdown;let html='<div class="cp-policy"><strong>'+t('تصحيح النطاق والتقدم الاختياري — سنويًا','Band correction and optional progression — annual')+'</strong><p>'+t('تصحيح الحد الأدنى: ','Minimum correction: ')+money(r.annualMinimumAdjustmentCost,c)+' · '+t('التقدم الاختياري: ','Optional progression: ')+money(r.annualOptionalProgressionCost,c)+'</p><small>'+t('نسبة المقارنة بالمنتصف لا تقيس أداء الموظف.','Compa-ratio does not measure employee performance.')+'</small></div>';
 if(v.review?.scope==='homogeneous-cohort-assumption')html+='<p class="cp-warning">'+t('افتراض صريح: جميع أفراد هذه المجموعة لهم الراتب والبدلات والنظام نفسه. استخدم قائمة الشاغلين للرواتب المختلفة.','Explicit assumption: everyone in this cohort has identical salary, benefits and regime. Use an incumbent roster for different salaries.')+'</p>';
 if(v.review?.warnings.length)html+='<p class="cp-warning">'+t('تتطلب هذه الأرقام مراجعة الفترة والحجم؛ تم تسجيل تأكيد المستخدم.','These figures trigger period/scale review; user confirmation is recorded.')+'</p>';
 if(b?.mode==='saudi')html+='<div class="cp-cost"><strong>'+t('تفصيل للفرد — تكلفة سنوية عند تاريخ ','Per person — annualized cost at ')+esc(b.asOf)+'</strong><dl>'+[[t('الأجر الخاضع للتأمينات شهريًا','Monthly contributory wage'),b.contributoryWage],[t('تأمينات صاحب العمل سنويًا','Annual employer GOSI'),b.annualGosi],[t('التأمين الطبي السنوي','Annual medical'),b.medicalAnnual],[t('تراكم سنة خدمة إضافية','One further year of service accrual'),b.annualEosServiceAccrual]].map(x=>'<dt>'+x[0]+'</dt><dd>'+money(x[1],c)+'</dd>').join('')+'</dl><p>'+t('معاشات: ','Pension: ')+b.pensionRate+'% · '+t('ساند: ','SANED: ')+b.sanedRate+'% · '+t('أخطار: ','Hazards: ')+b.occupationalRate+'%</p><p>'+t('النسب والأجر ثابتة عند التاريخ المدخل؛ ليس توقعًا لنسب الأشهر القادمة. نهاية الخدمة تقدير تكلفة سنة إضافية، وليست مخالصة نهائية أو التزامًا اكتواريًا وفق IAS 19.','Rates and wage are fixed at the selected date, not a future-month forecast. EOS estimates one more service year, not a termination settlement or IAS 19 actuarial liability.')+'</p>'+b.sources.map(x=>'<a href="'+esc(x.url)+'" target="_blank" rel="noopener">'+esc(x.id)+'</a>').join(' · ')+'</div>';
 if(v.incumbents)html+='<div class="cp-roster-results"><h3>'+t('نتائج كل شاغل','Individual results')+'</h3><div class="mp-table-wrap"><table><thead><tr>'+[t('الرمز','ID'),t('الحالي','Current'),t('المقترح','Proposed'),t('تصحيح / سنة','Correction / year'),t('تقدم / سنة','Progression / year'),t('التكلفة / سنة','Cost / year')].map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+v.incumbents.map(x=>'<tr><td>'+esc(x.id)+'</td>'+[x.input.currentSalary,x.result.recommendedSalary,x.result.annualMinimumAdjustmentCost,x.result.annualOptionalProgressionCost,x.result.annualEmployerCost].map(n=>'<td>'+money(n,c)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><p>'+t('تفاصيل التأمينات ونهاية الخدمة لكل فرد محفوظة في تصدير السيناريو.','Individual GOSI and service-accrual breakdowns are included in the scenario export.')+'</p></div>';
 return html;
}

})();
